RISKS = [
    ("browser", "user cannot complete checkout"),
    ("unit",    "discount math wrong"),
    ("a11y",    "keyboard/contrast fails"),
    ("api",     "cart accepts stale price"),
    ("unit",    "tax rounding wrong"),
    ("api",     "coupon reuse not rejected"),
]

LAYER_COST = {"unit": 0, "api": 1, "browser": 2, "a11y": 3}

def build_gate(risks):
    return sorted(risks, key=lambda r: LAYER_COST[r[0]])

def main():
    gate = build_gate(RISKS)
    for layer, risk in gate:
        print(f"{layer}: {risk}")
    layers = {layer for layer, _ in gate}
    print(f"gate covers {len(gate)} risks across {len(layers)} layers")

if __name__ == "__main__":
    main()

release-confidence-model.code:
RETRIES_IN_CI = 0

CHECKS = [
    {"name": "unit",     "status": "pass", "triaged": True,  "retries": 0},
    {"name": "contract", "status": "pass", "triaged": True,  "retries": 0},
    {"name": "browser",  "status": "pass", "triaged": True,  "retries": 2},
    {"name": "a11y",     "status": "pass", "triaged": False, "retries": 0},
]


def is_confident(check):
    return (
        check["status"] == "pass"
        and check["triaged"] is True
        and check["retries"] == RETRIES_IN_CI
    )


def release_decision(checks):
    return "SHIP" if all(is_confident(c) for c in checks) else "BLOCK"


for check in CHECKS:
    label = "confident" if is_confident(check) else "not-confident"
    print(f"{check['name']}: {label}")

print(f"decision: {release_decision(CHECKS)}")

unit-integration-boundary.code:
TESTS = [
    ("applyDiscount(100, 0.1) equals 90",            "arithmetic result"),
    ("empty cart applyDiscount(0, 0.1) equals 0",    "arithmetic result"),
    ("POST /api/checkout returns HTTP 200",          "response status code"),
    ("checkout body.total is a number",              "response field type"),
    ("shopper sees '$90.00' in the order summary",   "visible text on screen"),
]

OWNER_TO_LAYER = {
    "arithmetic result":   "unit",
    "response status code": "contract",
    "response field type":  "contract",
    "visible text on screen": "browser",
}


def apply_discount(subtotal, rate):
    return subtotal * (1 - rate)


def classify(owns):
    return OWNER_TO_LAYER[owns]


def main():
    print(f"unit: applyDiscount(100, 0.1) = {apply_discount(100, 0.1)}")
    print(f"unit: applyDiscount(0, 0.1) = {apply_discount(0, 0.1)}")

    counts = {"unit": 0, "contract": 0, "browser": 0}
    for description, owns in TESTS:
        layer = classify(owns)
        counts[layer] += 1
        print(f"{layer}: {description}")

    print(
        f"pyramid: unit={counts['unit']} contract={counts['contract']} browser={counts['browser']}"
    )


if __name__ == "__main__":
    main()

