import re

STATUS_CODE = 201
BODY = {
    "order_id": "3f2504e0-4f89-41d3-9a0c-0305e82c3301",
    "status": "confirmed",
    "amount_cents": 4200,
    "currency": "USD",
    "line_items": [
        {"sku": "SKU-1", "qty": 2},
        {"sku": "SKU-9", "qty": 1},
    ],
}

UUID_RE = re.compile(
    r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
)
ALLOWED_STATUS = {"confirmed", "pending", "failed"}


def validate(status_code, body):
    """Return a list of human-readable contract violations (empty == OK)."""
    failures = []

    if status_code != 201:
        failures.append(f"status_code: expected 201, got {status_code}")

    order_id = body.get("order_id")
    if not isinstance(order_id, str) or not UUID_RE.match(order_id):
        failures.append("order_id: not a valid uuid")

    st = body.get("status")
    if st not in ALLOWED_STATUS:
        failures.append(f"status: {st!r} not in enum")

    amount = body.get("amount_cents")
    if not isinstance(amount, int) or isinstance(amount, bool) or amount < 0:
        failures.append("amount_cents: not a nonnegative int")

    currency = body.get("currency")
    if not isinstance(currency, str) or len(currency) != 3:
        failures.append("currency: must be length 3")

    items = body.get("line_items")
    if not isinstance(items, list) or len(items) == 0:
        failures.append("line_items: must be non-empty array")
    else:
        for i, item in enumerate(items):
            qty = item.get("qty") if isinstance(item, dict) else None
            if not isinstance(qty, int) or isinstance(qty, bool) or qty < 1:
                failures.append(f"line_items[{i}].qty: not a positive int")

    return failures


fails = validate(STATUS_CODE, BODY)
if not fails:
    print("CONTRACT OK")
    print("fields_checked: 6")
    print(f"line_items: {len(BODY['line_items'])}")
else:
    print("CONTRACT VIOLATED")
    for f in fails:
        print(f"- {f}")

