class FakeDB:
    def __init__(self):
        self.users = set()

    def seed_user(self, email):
        if email in self.users:
            raise RuntimeError(f"user already exists: {email}")
        self.users.add(email)

    def delete_user(self, email):
        self.users.discard(email)


DB = FakeDB()

_counter = 0
def next_id():
    global _counter
    _counter += 1
    return _counter


def checkout_user():
    uid = next_id()
    email = f"buyer+{uid}@test.dev"
    DB.seed_user(email)
    try:
        yield email
    finally:
        DB.delete_user(email)


# --- test harness (given, do not change) ---
def run_test(test_fn):
    gen = checkout_user()
    email = next(gen)          # setup + hand state to the test
    passed = True
    try:
        test_fn(email)
    except AssertionError:
        passed = False
    finally:
        try:
            next(gen)          # force teardown, always
        except StopIteration:
            pass
    return passed


def test_ok(email):
    assert email.startswith("buyer+")

def test_fails(email):
    assert False


r1 = run_test(test_ok)
r2 = run_test(test_fails)
r3 = run_test(test_ok)

print(f"test 1 passed: {r1}")
print(f"test 2 passed: {r2}")
print(f"test 3 passed: {r3}")
print(f"leaked users: {len(DB.users)}")
print(f"unique emails used: {_counter}")

test-data-isolation.code:
from typing import Dict


class UserStore:
    """A fake backend user store (stands in for a real API)."""

    def __init__(self) -> None:
        self._users: Dict[str, dict] = {}
        self._next_id = 1

    def create(self, email: str) -> dict:
        for u in self._users.values():
            if u["email"] == email:
                raise ValueError(f"duplicate email: {email}")
        uid = f"u{self._next_id}"
        self._next_id += 1
        user = {"id": uid, "email": email}
        self._users[uid] = user
        return user

    def delete(self, user_id: str) -> None:
        self._users.pop(user_id, None)

    def count(self) -> int:
        return len(self._users)


def isolation_key(worker_index: int, seq: int, title: str) -> str:
    return f"{worker_index}-{seq}-{title}"


TESTS = [
    (0, "signup flow"),
    (1, "signup flow"),
    (0, "login flow"),
    (1, "login flow"),
]


def run_test(store: UserStore, worker_index: int, seq: int, title: str) -> str:
    key = isolation_key(worker_index, seq, title)
    email = f"qa+{key}@example.test"
    user = store.create(email)
    try:
        result = f"{title} -> {user['email']}"
    finally:
        store.delete(user["id"])
    return result


def main() -> None:
    store = UserStore()
    for seq, (worker_index, title) in enumerate(TESTS):
        print(run_test(store, worker_index, seq, title))
    print(f"residual users: {store.count()}")


if __name__ == "__main__":
    main()

