RESPONSES = {
    "anon_order": {
        "status": 403,
        "headers": {"content-type": "application/json"},
        "text": '{"error":"forbidden"}',
    },
    "checkout": {
        "status": 200,
        "headers": {
            "content-type": "text/html",
            "strict-transport-security": "max-age=31536000; includeSubDomains",
            "x-content-type-options": "nosniff",
            "content-security-policy": "default-src 'self'",
        },
        "text": "<html>checkout</html>",
    },
    "order_authed": {
        "status": 200,
        "headers": {"content-type": "application/json"},
        "text": '{"id":"ord_1001","total":4200,"card_last4":"1111"}',
    },
}


def run_smoke_checks(responses):
    """Return [(name, ok), ...] for the three invariants, in order."""
    results = []

    anon = responses["anon_order"]
    denied = anon["status"] in (401, 403) and "line_items" not in anon["text"]
    results.append(("anon-cannot-read-order", denied))

    headers = responses["checkout"]["headers"]
    headers_ok = (
        "strict-transport-security" in headers
        and headers.get("x-content-type-options") == "nosniff"
        and "content-security-policy" in headers
    )
    results.append(("checkout-security-headers", headers_ok))

    body = responses["order_authed"]["text"]
    no_pan = "4111111111111111" not in body
    results.append(("order-no-pan-leak", no_pan))

    return results


def main():
    results = run_smoke_checks(RESPONSES)
    for name, ok in results:
        print(f"{name}: {'PASS' if ok else 'FAIL'}")
    passed = sum(1 for _, ok in results if ok)
    print(f"{passed}/{len(results)} checks passed")


if __name__ == "__main__":
    main()

quality-review-board.code:
RISK_REGISTER = [
    {"id": "checkout-submit", "spec": "checkout.spec.ts", "likelihood": 4, "impact": 5, "revenue": 90000},
    {"id": "pricing-tax",     "spec": "pricing.spec.ts",  "likelihood": 3, "impact": 5, "revenue": 60000},
    {"id": "orders-api",      "spec": "orders.spec.ts",   "likelihood": 4, "impact": 4, "revenue": 40000},
    {"id": "search-slow",     "spec": "search.spec.ts",   "likelihood": 5, "impact": 2, "revenue": 8000},
]
TEST_BUDGET = 3

SPEC_ATTEMPTS = {
    "checkout.spec.ts": ["PASS", "FAIL", "PASS", "PASS", "PASS"],
    "pricing.spec.ts":  ["FAIL", "FAIL", "FAIL", "FAIL", "FAIL"],
    "orders.spec.ts":   ["PASS", "PASS", "PASS", "PASS", "PASS"],
    "search.spec.ts":   ["FAIL", "PASS", "FAIL", "PASS", "PASS"],
}
FLAKE_OWNERS = {"search.spec.ts": "sdet-anna"}

A11Y = [
    {"state": "cart", "severity": "minor"},
    {"state": "payment", "severity": "serious"},
]
BLOCKING_A11Y = {"serious", "critical"}


def exposure(r):
    return r["likelihood"] * r["impact"] * r["revenue"]


def verdict(attempts):
    passed = sum(1 for a in attempts if a == "PASS")
    total = len(attempts)
    if passed == total:
        return "STABLE", passed, total
    if passed == 0:
        return "BROKEN", passed, total
    return "FLAKE", passed, total


ranked = sorted(RISK_REGISTER, key=lambda r: (-exposure(r), r["id"]))
planned_specs = {r["spec"] for r in ranked[:TEST_BUDGET]}

print("PLAN (exposure-ranked, Module 1):")
for i, r in enumerate(ranked, 1):
    tag = "PLANNED" if r["spec"] in planned_specs else "below-cut"
    print(f"{i}. {r['id']} [{r['spec']}] exposure={exposure(r)} {tag}")

print("\nRULINGS (Module 3, --repeat-each=5):")
rulings = {}
for spec in sorted(SPEC_ATTEMPTS):
    label, passed, total = verdict(SPEC_ATTEMPTS[spec])
    rulings[spec] = label
    print(f"{spec}: {label} ({passed}/{total})")

print("\nA11Y (Module 4):")
for a in A11Y:
    print(f"{a['state']}: {a['severity']}")

hold_reasons = []
for r in ranked[:TEST_BUDGET]:
    spec = r["spec"]
    label = rulings.get(spec)
    if label == "BROKEN":
        hold_reasons.append(f"{spec} BROKEN on planned risk {r['id']} (exposure {exposure(r)})")
    elif label == "FLAKE" and spec not in FLAKE_OWNERS:
        hold_reasons.append(f"{spec} FLAKE on planned risk {r['id']} with no named owner")
for a in A11Y:
    if a["severity"] in BLOCKING_A11Y:
        hold_reasons.append(f"a11y {a['severity']} defect: {a['state']}")

print("\nHOLD REASONS:")
for reason in hold_reasons:
    print(f"- {reason}")

decision = "HOLD" if hold_reasons else "SHIP"
print(f"\nVERDICT: {decision}")
print("REVERSAL: ship when every HOLD reason clears -- the BROKEN spec passes --repeat-each, "
      "each unowned planned flake gets a named owner, and every serious/critical a11y defect is fixed")
